describe("when the info state changes", () => {
    beforeEach(async () => {
        mocked(client.relations).mockResolvedValueOnce({ events: [] });
        setUpChunkEvents([]);
        infoEvent = mkInfoEvent(VoiceBroadcastInfoState.Started);
        playback = await mkPlayback();
    });

    const emitInfoState = (state: VoiceBroadcastInfoState, timestamp: number): void => {
        // @ts-ignore
        playback.infoRelationHelper.emit(RelationsHelperEvent.Add, mkInfoEvent(state, timestamp));
    };

    it("changes liveness only when the mapped value changes", () => {
        expect(playback.getLiveness()).toBe("live");

        emitInfoState(VoiceBroadcastInfoState.Resumed, 1);
        expect(playback.getLiveness()).toBe("live");
        expect(onLivenessChanged).not.toHaveBeenCalled();

        emitInfoState(VoiceBroadcastInfoState.Paused, 2);
        expect(playback.getLiveness()).toBe("grey");
        expect(onLivenessChanged).toHaveBeenCalledTimes(1);
        expect(onLivenessChanged).toHaveBeenLastCalledWith("grey");

        emitInfoState(VoiceBroadcastInfoState.Paused, 3);
        expect(onLivenessChanged).toHaveBeenCalledTimes(1);

        emitInfoState(VoiceBroadcastInfoState.Resumed, 4);
        expect(playback.getLiveness()).toBe("live");
        expect(onLivenessChanged).toHaveBeenCalledTimes(2);
        expect(onLivenessChanged).toHaveBeenLastCalledWith("live");

        emitInfoState(VoiceBroadcastInfoState.Stopped, 5);
        expect(playback.getLiveness()).toBe("not-live");
        expect(onLivenessChanged).toHaveBeenCalledTimes(3);
        expect(onLivenessChanged).toHaveBeenLastCalledWith("not-live");
    });

    it("reports the updated liveness to info state listeners", () => {
        const livenessAtInfoStateChanged: VoiceBroadcastLiveness[] = [];
        playback.on(VoiceBroadcastPlaybackEvent.InfoStateChanged, () => {
            livenessAtInfoStateChanged.push(playback.getLiveness());
        });

        emitInfoState(VoiceBroadcastInfoState.Paused, 1);
        emitInfoState(VoiceBroadcastInfoState.Resumed, 2);

        expect(livenessAtInfoStateChanged).toEqual(["grey", "live"]);
    });

    it.each(["unknown", undefined])("defaults to not-live when a newer info event has state %s", (state) => {
        emitInfoState(state as VoiceBroadcastInfoState, 1);

        expect(playback.getLiveness()).toBe("not-live");
        expect(onLivenessChanged).toHaveBeenCalledTimes(1);
        expect(onLivenessChanged).toHaveBeenCalledWith("not-live");
    });
});

